mapper.select:
SELECT DATE(create_time) AS statDate, COUNT(*) AS orders, SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled, COALESCE(SUM(CASE WHEN status = 'DELIVERED' THEN price ELSE 0 END), 0) AS revenue FROM delivery_order WHERE deleted = 0
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY DATE(create_time) ORDER BY statDate DESC
